public class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS_LIMIT = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate inputs
        validateInputs(objectApiName, fields, filters, orderByField, maxRows);

        // Normalize object API name
        String normalizedObjectName = objectApiName.toLowerCase();

        // Get the describe for the object
        SObjectType objectType = getSObjectType(normalizedObjectName);
        if (objectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        // Check object read access
        if (!objectType.getDescribe().isAccessible()) {
            throw new SearchException('User does not have read access to object: ' + objectApiName);
        }

        Map<String, SObjectField> fieldMap = objectType.getDescribe().fields.getMap();

        // Validate fields
        validateFields(fieldMap, fields, 'fields', false);

        // Validate filter fields
        if (filters != null && !filters.isEmpty()) {
            validateFields(fieldMap, new List<String>(filters.keySet()), 'filter keys', true);
        }

        // Validate order by field
        if (String.isNotBlank(orderByField)) {
            List<String> orderByFields = new List<String> { orderByField };
            validateFields(fieldMap, orderByFields, 'orderByField', false);
        }

        // Build the SOQL query
        String query = buildQuery(objectType, fieldMap, fields, filters, orderByField, maxRows);

        // Execute the query
        try {
            return Database.query(query);
        } catch (Exception e) {
            throw new SearchException('Query execution failed: ' + e.getMessage());
        }
    }

    private static void validateInputs(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name cannot be blank');
        }

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty');
        }

        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS_LIMIT) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS_LIMIT);
        }
    }

    private static SObjectType getSObjectType(String normalizedObjectName) {
        try {
            return Schema.getGlobalDescribe().get(normalizedObjectName);
        } catch (Exception e) {
            return null;
        }
    }

    private static void validateFields(
        Map<String, SObjectField> fieldMap,
        List<String> fieldList,
        String fieldContext,
        Boolean checkFilterability
    ) {
        for (String fieldName : fieldList) {
            String normalizedFieldName = fieldName.toLowerCase();
            SObjectField field = fieldMap.get(normalizedFieldName);

            if (field == null) {
                throw new SearchException('Field does not exist: ' + fieldName);
            }

            DescribeFieldResult dfr = field.getDescribe();

            // Check field accessibility
            if (!dfr.isAccessible()) {
                throw new SearchException('User does not have read access to field: ' + fieldName);
            }

            // Check filterability for filter keys
            if (checkFilterability && !dfr.isFilterable()) {
                throw new SearchException('Field cannot be filtered: ' + fieldName);
            }

            // Check sortability for order by field
            if (fieldContext == 'orderByField' && !dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + fieldName);
            }
        }
    }

    private static String buildQuery(
        SObjectType objectType,
        Map<String, SObjectField> fieldMap,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        String queryStr = 'SELECT Id';

        // Add fields
        for (String field : fields) {
            queryStr += ', ' + field;
        }

        queryStr += ' FROM ' + objectType.getDescribe().getName();

        // Add WHERE clause if filters exist
        if (filters != null && !filters.isEmpty()) {
            queryStr += ' WHERE';
            boolean isFirst = true;

            for (String filterKey : filters.keySet()) {
                if (!isFirst) {
                    queryStr += ' AND';
                }

                Object filterValue = filters.get(filterKey);
                String normalizedFieldName = filterKey.toLowerCase();
                SObjectField field = fieldMap.get(normalizedFieldName);
                String fieldApiName = field.getDescribe().getName();

                queryStr += ' ' + fieldApiName + ' = ' + formatFilterValue(filterValue);
                isFirst = false;
            }
        }

        // Add ORDER BY clause
        if (String.isNotBlank(orderByField)) {
            String normalizedOrderField = orderByField.toLowerCase();
            SObjectField field = fieldMap.get(normalizedOrderField);
            String fieldApiName = field.getDescribe().getName();
            queryStr += ' ORDER BY ' + fieldApiName + ' ASC';
        }

        // Add LIMIT clause
        queryStr += ' LIMIT ' + maxRows;

        return queryStr;
    }

    private static String formatFilterValue(Object value) {
        if (value == null) {
            return 'null';
        }

        if (value instanceof String) {
            String strValue = (String) value;
            // Escape single quotes for SOQL
            strValue = strValue.replace('\'', '\'\'');
            return '\'' + strValue + '\'';
        }

        if (value instanceof Boolean) {
            return String.valueOf(value);
        }

        if (value instanceof Date) {
            Date dateValue = (Date) value;
            return dateValue.format();
        }

        if (value instanceof Decimal) {
            return String.valueOf(value);
        }

        if (value instanceof Integer) {
            return String.valueOf(value);
        }

        if (value instanceof Id) {
            Id idValue = (Id) value;
            return '\'' + idValue + '\'';
        }

        // Fallback for unknown types
        throw new SearchException('Unsupported filter value type');
    }
}
