public class AccountRatingService {

    @future
    public static void recalculate(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Query all open opportunities for these accounts
        List<Opportunity> opportunities = [
            SELECT AccountId, Amount, StageName
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND StageName NOT IN ('Closed Won', 'Closed Lost')
            WITH USER_MODE
        ];

        // Group opportunities by AccountId
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : opportunities) {
            if (!oppsByAccount.containsKey(opp.AccountId)) {
                oppsByAccount.put(opp.AccountId, new List<Opportunity>());
            }
            oppsByAccount.get(opp.AccountId).add(opp);
        }

        // Determine rating for each account
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            String rating = determineRating(oppsByAccount.get(accountId));
            accountsToUpdate.add(new Account(Id = accountId, Rating = rating));
        }

        // Update accounts
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static String determineRating(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return 'Cold';
        }

        // Check if any opportunity has Amount >= 100,000
        for (Opportunity opp : opportunities) {
            if (opp.Amount != null && opp.Amount >= 100000) {
                return 'Hot';
            }
        }

        // Has open opportunities but none >= 100,000
        return 'Warm';
    }
}
