public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> results = new List<Id>();

        // Pre-normalize all contact emails to avoid repeated normalization in inner loop
        List<String> normalizedContactEmails = new List<String>();
        for (Contact contact : contacts) {
            normalizedContactEmails.add(normalizeEmail(contact.Email));
        }

        for (Lead lead : leads) {
            Id matchedContactId = null;
            String leadEmail = normalizeEmail(lead.Email);

            // Only search if lead has a valid email
            if (String.isNotBlank(leadEmail)) {
                for (Integer i = 0; i < contacts.size(); i++) {
                    if (leadEmail == normalizedContactEmails.get(i)) {
                        matchedContactId = contacts.get(i).Id;
                        break; // Return first match in contacts order
                    }
                }
            }

            results.add(matchedContactId);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
