        if (!trimmedLabel) {
            return;
        }
        this._tasks.push({ id: `new-${this.nextId++}`, label: trimmedLabel, done: false });
        this._tasks = [...this._tasks];
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label: trimmedLabel } }));
        this.newLabel = '';
    }

    handleToggle(event) {
        const li = event.currentTarget.closest('li');
        const taskId = li.dataset.id;
        const task = this._tasks.find((t) => t.id === taskId);
        if (task) {
            task.done = !task.done;
            this._tasks = [...this._tasks];
        }
    }
