     * Gets all contacts in the household
     */
    private static Set<Id> getHouseholdMembers(Id householdAccountId) {
        Set<Id> memberIds = new Set<Id>();

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
        ];

        for (Contact member : householdMembers) {
            memberIds.add(member.Id);
        }

        return memberIds;
    }

