public class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Handle null or empty input
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> parentIds = new Set<Id>(parentIdByChildId.values());
        Set<Id> childIds = new Set<Id>(parentIdByChildId.keySet());

        // Single SOQL query to find all existing relationships between these contacts
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
               OR (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
        ]) {
            // Store pairs in both directions to catch relationships in either direction
            String pair1 = rel.npe4__Contact__c + ':' + rel.npe4__RelatedContact__c;
            String pair2 = rel.npe4__RelatedContact__c + ':' + rel.npe4__Contact__c;
            existingPairs.add(pair1);
            existingPairs.add(pair2);
        }

        // Build list of new relationship records
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Check if relationship already exists in either direction
            String pairKey = parentId + ':' + childId;
            if (!existingPairs.contains(pairKey)) {
                npe4__Relationship__c rel = new npe4__Relationship__c();
                rel.npe4__Contact__c = parentId;
                rel.npe4__RelatedContact__c = childId;
                rel.npe4__Type__c = 'Parent';
                rel.npe4__Status__c = 'Current';
                relationshipsToInsert.add(rel);
            }
        }

        // Single DML statement
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }
}
