public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    override public DmlWrapper run(List<SObject> newlist, List<SObject> oldlist,
            npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {

        DmlWrapper dmlWrapper = new DmlWrapper();
        List<Task> tasksToCreate = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            tasksToCreate = createTasksForInserts(newlist);
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            tasksToCreate = createTasksForUpdates(newlist, oldlist);
        }

        if (!tasksToCreate.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll(tasksToCreate);
        }

        return dmlWrapper;
    }

    /**
     * Create tasks for newly inserted opportunities that are major gifts
     */
    private List<Task> createTasksForInserts(List<SObject> newlist) {
        List<Task> tasks = new List<Task>();

        for (SObject obj : newlist) {
            Opportunity opp = (Opportunity) obj;

            if (isMajorGift(opp)) {
                Task t = createTask(opp);
                if (t != null) {
                    tasks.add(t);
                }
            }
        }

        return tasks;
    }

    /**
     * Create tasks for updated opportunities that became major gifts
     */
    private List<Task> createTasksForUpdates(List<SObject> newlist, List<SObject> oldlist) {
        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];
            Opportunity oldOpp = (Opportunity) oldlist[i];

            // Only create task if the opportunity became a major gift
            // (wasn't before, but is now)
            if (isMajorGift(newOpp) && !isMajorGift(oldOpp)) {
                Task t = createTask(newOpp);
                if (t != null) {
                    tasks.add(t);
                }
            }
        }

        return tasks;
    }

    /**
     * Check if an opportunity qualifies as a major gift
     */
    private Boolean isMajorGift(Opportunity opp) {
        return opp != null 
            && opp.Amount != null 
            && opp.Amount >= MAJOR_GIFT_THRESHOLD
            && opp.StageName == CLOSED_WON_STAGE;
