```apex
public class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Query accounts to update
        List<Account> accountsToUpdate = [
            SELECT Id, OwnerId
            FROM Account
            WHERE Id IN :accountIds
            WITH USER_MODE
        ];

        // Query contacts for these accounts
        List<Contact> contactsToUpdate = [
            SELECT Id, OwnerId
            FROM Contact
            WHERE AccountId IN :accountIds
            WITH USER_MODE
        ];

        // Set new owner on accounts
        for (Account acc : accountsToUpdate) {
            acc.OwnerId = newOwnerId;
        }

        // Set new owner on contacts
        for (Contact con : contactsToUpdate) {
            con.OwnerId = newOwnerId;
        }

        // Bypass Account trigger actions to avoid expensive territory recalculation
        TriggerBase.bypass('Account');
        try {
            // Update accounts with bypass active
            update accountsToUpdate;
        } finally {
            // Clear bypass immediately after update, ensuring normal behavior for rest of transaction
            TriggerBase.clearBypass('Account');
        }

        // Update contacts - trigger actions will run normally since Contact is not bypassed
        update contactsToUpdate;
    }
}
```

