public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        validateNoDuplicateEmails(contacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        Map<Id, Contact> oldContactsMap = new Map<Id, Contact>((List<Contact>) triggerOld);
        validateNoDuplicateEmails(contacts, oldContactsMap);
    }

    private void validateNoDuplicateEmails(List<Contact> contacts, Map<Id, Contact> oldContactsMap) {
        // Determine which contacts need to be checked
        Set<Id> accountIds = new Set<Id>();
        List<Contact> contactsToCheck = new List<Contact>();

        for (Contact contact : contacts) {
            // Skip if no account or no email
            if (contact.AccountId == null || contact.Email == null) {
                continue;
            }

            // For updates, only check if Email or AccountId changed
            if (oldContactsMap != null) {
                Contact oldContact = oldContactsMap.get(contact.Id);
                if (oldContact != null) {
                    if (contact.Email == oldContact.Email && contact.AccountId == oldContact.AccountId) {
                        continue; // Neither field changed
                    }
                }
            }

            accountIds.add(contact.AccountId);
            contactsToCheck.add(contact);
        }

        // If nothing to check, exit early
        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Single SOQL query: fetch all contacts on these accounts with their emails
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            WITH USER_MODE
        ];

        // Build a map of (AccountId, Email_normalized) -> Contact Id
        Map<String, Id> existingEmailMap = new Map<String, Id>();
        for (Contact existing : existingContacts) {
            if (existing.Email != null) {
                String key = existing.AccountId + '|' + existing.Email.toLowerCase();
                existingEmailMap.put(key, existing.Id);
            }
        }

        // Track which (AccountId, Email) combinations we've seen in this batch
        Set<String> seenInBatch = new Set<String>();

        // Validate each contact
        for (Contact contact : contactsToCheck) {
            String normalizedEmail = contact.Email.toLowerCase();
            String key = contact.AccountId + '|' + normalizedEmail;

            // Check if this combination already exists in database (excluding self on update)
            if (existingEmailMap.containsKey(key)) {
                Id existingId = existingEmailMap.get(key);
                // On update, don't conflict with self
                if (oldContactsMap == null || existingId != contact.Id) {
                    contact.addError(ERROR_MESSAGE);
                    continue; // Don't process this contact further
                }
            }

            // Check if we've already seen this combination in this batch
            if (seenInBatch.contains(key)) {
                contact.addError(ERROR_MESSAGE);
            } else {
                seenInBatch.add(key);
            }
        }
    }
}
