public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToCreate = new List<Task>();

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);

        for (Opportunity newOpp : triggerNew) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);

            // Only process on first execution of after-update for this opportunity in this transaction
            Integer timesSeenAfterUpdate = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(newOpp.Id);
            if (timesSeenAfterUpdate != null && timesSeenAfterUpdate > 1) {
                continue;
            }

            // Check if Amount actually changed
            Decimal newAmount = newOpp.Amount;
            Decimal oldAmount = oldOpp.Amount;

            if (newAmount != oldAmount) {
                // Create audit task
                Task auditTask = new Task();
                auditTask.Subject = 'Amount changed';
                auditTask.WhatId = newOpp.Id;
                auditTask.Status = 'Completed';

                tasksToCreate.add(auditTask);
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
