        public void beforeInsert(List<SObject> triggerNew) {
            List<Contact> contacts = (List<Contact>) triggerNew;
            Set<Id> accountIds = new Set<Id>();

            // Collect all Account IDs from contacts
            for (Contact c : contacts) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            // Query accounts and populate the singleton's map
            Map<Id, Account> queriedAccounts = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                queriedAccounts = new Map<Id, Account>(
                    [
                        SELECT
                            Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = queriedAccounts;
        }
    }
}
